import{REST as s}from"../../shared/js/avatar-figure-1.0.0.min.js";export const MAX_HEAD_TURN=1.1,ARM_POSES=Object.freeze({stand:null,dismiss:Object.freeze({z:.4,x:-1.1,fore:-1.1,twist:Math.PI}),approve:Object.freeze({z:.3,x:-1.9,fore:-.4,twist:0}),present:Object.freeze({z:1.25,x:-.5,fore:-.6,twist:0}),shake:Object.freeze({z:-.16,x:-.85,fore:-1.26,twist:0}),point:Object.freeze({z:.87,x:-1.09,fore:-.51,twist:0}),aim:Object.freeze({z:-.13,x:-1.76,fore:.07,twist:0}),lookBack:null}),POINTING=Object.freeze(["point"]),HANDSHAKE=Object.freeze({gap:.8,aside:.23,turn:.5}),HEAD_TURNS=Object.freeze({stand:0,dismiss:.45,approve:0,present:.25,shake:0,point:.35,aim:0,lookBack:.95}),STRIDE=Object.freeze({most:.55,arm:.35}),MAX_NOD=.6;export function legsFor(r){const e=Math.max(-STRIDE.most,Math.min(STRIDE.most,Number(r)||0));return{right:-e,left:e}}export function nodFor(r){return Math.max(-MAX_NOD,Math.min(MAX_NOD,Number(r)||0))}export const POSES=Object.freeze(Object.keys(ARM_POSES)),SIDES=Object.freeze(["right","left"]);export function armsFor(r,e="right"){const o=ARM_POSES[r],t={...s};return o?e==="left"?{right:t,left:{...o}}:{right:{...o},left:t}:{right:{...t},left:{...t}}}export function headTurnFor(r,e="right"){const o=n=>Math.max(-MAX_HEAD_TURN,Math.min(MAX_HEAD_TURN,n));if(typeof e=="number")return Number.isFinite(e)?o(e):0;const t=o(Math.max(0,HEAD_TURNS[r]||0));return t===0?0:e==="left"?t:-t}
